/**
 * Serializes finite JSON data deterministically for contract identity.
 *
 * Invariants:
 * - Object keys use canonical string order; cycles, sparse arrays and
 *   non-plain objects are rejected.
 */
export class CanonicalJsonError extends TypeError {
    code = 'CANONICAL_JSON_INVALID';
    constructor() {
        super('Value cannot be encoded as canonical JSON data.');
        this.name = 'CanonicalJsonError';
    }
}
export function canonicalJson(value) {
    return serialize(value, new Set());
}
export function compareCanonicalStrings(left, right) {
    return left < right ? -1 : left > right ? 1 : 0;
}
function serialize(value, ancestors) {
    if (value === null)
        return 'null';
    switch (typeof value) {
        case 'string':
            return JSON.stringify(value);
        case 'boolean':
            return value ? 'true' : 'false';
        case 'number':
            if (!Number.isFinite(value))
                throw new CanonicalJsonError();
            return JSON.stringify(value);
        case 'object': {
            const container = value;
            if (ancestors.has(container))
                throw new CanonicalJsonError();
            ancestors.add(container);
            try {
                return Array.isArray(container)
                    ? serializeArray(container, ancestors)
                    : serializeObject(container, ancestors);
            }
            finally {
                ancestors.delete(container);
            }
        }
        default:
            throw new CanonicalJsonError();
    }
}
function serializeArray(value, ancestors) {
    const parts = [];
    for (let index = 0; index < value.length; index += 1) {
        if (!Object.prototype.hasOwnProperty.call(value, index)) {
            throw new CanonicalJsonError();
        }
        parts.push(serialize(value[index], ancestors));
    }
    return `[${parts.join(',')}]`;
}
function serializeObject(value, ancestors) {
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
        throw new CanonicalJsonError();
    }
    const record = value;
    const parts = Object.keys(record)
        .sort(compareCanonicalStrings)
        .map((key) => `${JSON.stringify(key)}:${serialize(record[key], ancestors)}`);
    return `{${parts.join(',')}}`;
}
